const express = require('express');
const cors = require('cors');
// 1. ADIMDA OLUŞTURDUĞUMUZ VERİ DOSYASINI ÇAĞIRIYORUZ
const gercekMekanlar = require('./mekanlar'); 

const app = express();
app.use(cors());

// --- OTOMATİK ROTA ÜRETİCİ ---
// Gerçek mekanlar listesi 30 tane. Bunu 100'e tamamlamak için
// sanal (mock) veriler üretiyoruz.
const tumMekanlar = [...gercekMekanlar];
const eksikSayi = 100 - gercekMekanlar.length;

const kategoriler = ["Doğa", "Tarih", "Eğlence", "Yemek"];
const resimler = [
    "https://upload.wikimedia.org/wikipedia/commons/f/f3/Duden_Waterfalls_Antalya.jpg", // Doğa
    "https://upload.wikimedia.org/wikipedia/commons/e/e5/Kaleici_Antalya.jpg",         // Tarih
    "https://upload.wikimedia.org/wikipedia/commons/7/7d/Konyaalt%C4%B1_Beach.jpg",     // Eğlence
    "https://galeri13.uludagsozluk.com/645/7-mehmet_1848574.jpg"                        // Yemek
];

for (let i = 0; i < eksikSayi; i++) {
    const randomKatIndex = Math.floor(Math.random() * 4);
    const kategori = kategoriler[randomKatIndex];

    tumMekanlar.push({
        id: 1000 + i, // Çakışmasın diye ID'leri 1000'den başlattık
        ad: `Keşfedilmemiş Rota ${i + 1}`,
        kategori: kategori,
        sure: Math.floor(Math.random() * 120) + 30, // 30-150 dk arası
        ucret: Math.floor(Math.random() * 200),     // 0-200 TL arası
        lat: 36.8 + (Math.random() * 0.5),          // Antalya çevresinde rastgele koordinat
        lon: 30.7 + (Math.random() * 0.5),
        resim: resimler[randomKatIndex],
        aciklama: "Bu mekan henüz keşfedilmeyi bekliyor! AI tavsiyesi alarak detayları öğrenebilirsin."
    });
}

// API Endpoint
app.get('/api/rota', (req, res) => {
    res.json(tumMekanlar);
});

const PORT = 5000;
app.listen(PORT, () => {
    console.log(`✅ Server çalışıyor: http://localhost:${PORT}`);
    console.log(`📊 Toplam ${tumMekanlar.length} adet rota yüklendi!`);
});
